input.content:
import Link from "next/link";
import { Reveal } from "@/components/marketing/Reveal";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { CtaBand } from "@/components/marketing/sections";
import { FaqJsonLd } from "@/components/marketing/StructuredData";

/**
 * Shared layout for the game-server / gaming-VPS SEO landing pages.
 *
 * It renders the EXACT same markup as the hand-written /rust-server-hosting and
 * /minecraft-server-hosting pages (hero → intro prose → plans → why → steps →
 * guides → FAQ → related → CTA) so every new page reads as native. Each route
 * file owns its own `export const metadata` (Next requires it in the page file)
 * and passes real, game-specific copy + real Nxeon pricing in here.
 */

export type Cta = { label: string; href: string };
export type Plan = {
  /** Full heading, e.g. "16 GB" or "Max · 16 GB". */
  name: string;
  /** Displayed price, e.g. "$14.99". Rendered with a trailing "/mo". */
  price: string;
  /** Small right-aligned meta, e.g. "32 players" or "recommended". */
  meta?: string;
  blurb: string;
  popular?: boolean;
};
export type Link2 = { label: string; href: string };

export type GameLandingProps = {
  hero: {
    eyebrow?: string;
    title: string;
    highlight?: string;
    sub: string;
    primary?: Cta;
    secondary?: Cta;
  };
  /** Intro prose paragraphs (2–3). */
  intro: React.ReactNode[];
  plansTitle: string;
  plansSub: string;
  /** Where every plan card's button links, and its label. */
  plansCta: Cta;
  plans: Plan[];
  whyTitle: string;
  why: { title: string; body: string }[];
  stepsTitle: string;
  steps: { title: string; body: string }[];
  /** Optional "Related guides" — internal links to the matching blog posts. */
  guides?: Link2[];
  faq: { q: string; a: string }[];
  related: Link2[];
};

export function GameLandingPage(props: GameLandingProps) {
  const {
    hero,
    intro,
    plansTitle,
    plansSub,
    plansCta,
    plans,
    whyTitle,
    why,
    stepsTitle,
    steps,
    guides,
    faq,
    related,
  } = props;

  return (
    <>
      <FaqJsonLd items={faq} />

      <PageHero
        eyebrow={hero.eyebrow ?? "Game servers"}
        title={hero.title}
        highlight={hero.highlight}
        sub={hero.sub}
        primary={hero.primary}
        secondary={hero.secondary}
      />

      {/* Intro prose */}
      <Section tone="base" size="md">
        <div className="mx-auto max-w-3xl space-y-4 text-[15px] leading-relaxed text-slate-300">
          {intro.map((p, i) => (
            <Reveal as="p" key={i} delay={i * 60}>
              {p}
            </Reveal>
          ))}
        </div>
      </Section>

      {/* Plans */}
      <Section tone="panel" size="lg">
        <SectionTitle eyebrow="Plans" title={plansTitle} sub={plansSub} />
        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {plans.map((p, i) => (
            <Reveal
              key={p.name}
              delay={i * 60}
              className={`card relative ${p.popular ? "ring-1 ring-brand-400/40" : ""}`}
            >
              {p.popular && (
                <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-brand-500/20 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-brand-200">
                  Most popular
                </span>
              )}
              <div className="flex items-baseline justify-between">
                <h3 className="text-lg font-semibold text-white">{p.name}</h3>
                {p.meta && <span className="text-xs font-medium text-slate-500">{p.meta}</span>}
              </div>
              <p className="mt-3">
                <span className="text-3xl font-bold text-white">{p.price}</span>
                <span className="text-sm text-slate-500">/mo</span>
              </p>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{p.blurb}</p>
              <Link
                href={plansCta.href}
                className={`mt-5 block rounded-xl px-4 py-2.5 text-center text-sm font-semibold ${
                  p.popular ? "btn-primary" : "btn-secondary"
                }`}
              >
                {plansCta.label}
              </Link>
            </Reveal>
          ))}
        </div>
      </Section>

      {/* Why Nxeon */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="Why Nxeon" title={whyTitle} />
        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {why.map((w, i) => (
            <Reveal key={w.title} delay={i * 60} className="card">
              <h3 className="text-base font-semibold text-white">{w.title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-slate-400">{w.body}</p>
            </Reveal>
          ))}
        </div>
      </Section>

      {/* Steps */}
      <Section tone="panel" size="md">
        <SectionTitle eyebrow="Get started" title={stepsTitle} />
        <ol className="mx-auto mt-10 max-w-3xl space-y-3">
          {steps.map((s, i) => (
            <Reveal as="li" key={s.title} delay={i * 60} className="card flex gap-4">
              <span className="flex h-8 w-8 flex-none items-center justify-center rounded-lg bg-brand-500/20 text-sm font-bold text-brand-200">
                {i + 1}
              </span>
              <div>
                <h3 className="text-sm font-semibold text-white">{s.title}</h3>
                <p className="mt-1 text-sm leading-relaxed text-slate-400">{s.body}</p>
              </div>
            </Reveal>
          ))}
        </ol>
      </Section>

      {/* Related guides (internal links to matching blog posts) */}
      {guides && guides.length > 0 && (
        <Section tone="base" size="md">
          <SectionTitle
            eyebrow="Guides"
            title="Step-by-step setup guides"
            sub="Prefer to run it yourself, or just want to understand the specs? These walkthroughs cover it."
          />
          <div className="mx-auto mt-10 grid max-w-3xl gap-3 sm:grid-cols-2">
            {guides.map((g) => (
              <Link
                key={g.href}
                href={g.href}
                className="card card-hover flex items-center justify-between gap-3 text-sm font-medium text-slate-200"
              >
                {g.label}
                <span className="text-brand-300">→</span>
              </Link>
            ))}
          </div>
        </Section>
      )}

      {/* FAQ */}
      <Section tone={guides && guides.length > 0 ? "panel" : "base"} size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {faq.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {related.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

import type { Metadata } from "next";
import { GameLandingPage } from "@/components/marketing/GameLandingPage";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
